commands:
{ <iptables> -C f2b-SSH -j RETURN >/dev/null 2>&1; } || { <iptables> -N f2b-SSH || true; <iptables> -A f2b-SSH -j RETURN; }
for chain in $(echo 'INPUT' | sed 's/,/ /g'); do for proto in $(echo 'tcp' | sed 's/,/ /g'); do
{ <iptables> -C $chain -p $proto -m multiport --dports ssh,2222 -j f2b-SSH >/dev/null 2>&1; } || { <iptables> -I $chain -p $proto -m multiport --dports ssh,2222 -j f2b-SSH; }
done; done

{ <iptables> -C f2b-all -j RETURN >/dev/null 2>&1; } || { <iptables> -N f2b-all || true; <iptables> -A f2b-all -j RETURN; }
for chain in $(echo 'FORWARD' | sed 's/,/ /g'); do for proto in $(echo 'tcp' | sed 's/,/ /g'); do
{ <iptables> -C $chain -p $proto -j f2b-all >/dev/null 2>&1; } || { <iptables> -I $chain -p $proto -j f2b-all; }
done; done
